package com.hbm.machine.silex;
import com.hbm.fluid.FluidContainerRegistry;import com.hbm.item.fluid.FluidIdentifier;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Exact11+36 source slots and identifier/container/input shift ordering. */
public final class SilexMenu extends AbstractContainerMenu {
 public final Container machine;private final BlockPos position;public SilexMenu(int id,Inventory player,RegistryFriendlyByteBuf buffer){this(id,player,buffer.readBlockPos());}private SilexMenu(int id,Inventory player,BlockPos pos){this(id,player,player.player.level().getBlockEntity(pos) instanceof SilexBlockEntity machine?machine:new SimpleContainer(11),pos);}
 public SilexMenu(int id,Inventory player,Container machine,BlockPos pos){super(SilexContent.MENU.get(),id);checkContainerSize(machine,11);this.machine=machine;position=pos;machine.startOpen(player.player);addSlot(new Slot(machine,0,80,12));addSlot(new Slot(machine,1,8,24));addSlot(new Slot(machine,2,26,24));addSlot(new Slot(machine,3,44,24){@Override public boolean mayPlace(ItemStack stack){return false;}});addSlot(new com.hbm.recipe.generic.GenericOutputSlot(player.player,machine,4,116,90));for(int i=0;i<6;i++)addSlot(new com.hbm.recipe.generic.GenericOutputSlot(player.player,machine,5+i,134+i%2*18,72+i/2*18));for(int row=0;row<3;row++)for(int column=0;column<9;column++)addSlot(new Slot(player,9+row*9+column,8+column*18,140+row*18));for(int i=0;i<9;i++)addSlot(new Slot(player,i,8+i*18,198));}
 public BlockPos position(){return position;}@Override public boolean stillValid(Player player){return machine.stillValid(player);}@Override public void removed(Player player){super.removed(player);machine.stopOpen(player);}@Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size()||!getSlot(index).hasItem())return ItemStack.EMPTY;var slot=getSlot(index);var stack=slot.getItem();var copy=stack.copy();if(index<=10){if(!moveItemStackTo(stack,11,slots.size(),true))return ItemStack.EMPTY;}else{int target=stack.getItem() instanceof FluidIdentifier?1:machine instanceof SilexBlockEntity silex&&FluidContainerRegistry.getFluidContent(stack,silex.tank.getTankType())>0?2:0;if(!moveItemStackTo(stack,target,target+1,false))return ItemStack.EMPTY;}if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();slot.onTake(player,stack);return copy;}
}
